"""Living agent rules: keeps an auto-generated block inside ``CLAUDE.md`` / ``.cursorrules`` (or any
rules file) up to date with the real architecture, API routes, decisions, critical scars and hotspots.

Only the text between ``<!-- AETHER:START -->`` and ``<!-- AETHER:END -->`` is ever rewritten; everything
the user wrote outside the markers is preserved byte-for-byte (including CRLF line endings).
"""

from __future__ import annotations

import os
import re
import time
from pathlib import Path
from typing import Any

START_MARKER = "<!-- AETHER:START -->"
END_MARKER = "<!-- AETHER:END -->"
DEFAULT_TARGETS = ("CLAUDE.md", ".cursorrules")
_BLOCK = re.compile(re.escape(START_MARKER) + r"[\s\S]*?" + re.escape(END_MARKER))


def upsert_block(existing: str, block_body: str) -> str:
    """Insert or replace the managed block, preserving all content outside the markers."""
    newline = "\r\n" if "\r\n" in existing else "\n"
    body = block_body.replace("\r\n", "\n").strip("\n").replace("\n", newline)
    block = f"{START_MARKER}{newline}{body}{newline}{END_MARKER}"
    if _BLOCK.search(existing):
        return _BLOCK.sub(lambda _: block, existing, count=1)
    if not existing.strip():
        return block + newline
    sep = "" if existing.endswith(newline * 2) else (newline if existing.endswith(newline) else newline * 2)
    return f"{existing}{sep}{block}{newline}"


def extract_block(text: str) -> str | None:
    m = _BLOCK.search(text)
    return m.group(0) if m else None


def render_rules(data: dict[str, Any]) -> str:
    """Build the Markdown body of the managed block from kernel-provided facts."""
    c = data["counts"]
    out: list[str] = [
        "## AetherOS live context",
        "",
        # No index version / markdown counts here: the rules files are themselves indexed, so including them
        # would make every sync change the block again (the output must be a fixed point).
        f"_Auto-generated by `aether sync-rules` on {time.strftime('%Y-%m-%d')}. "
        "Edits inside this block are overwritten; write your own rules outside the markers._",
        "",
        f"- **Project:** `{data['project']}`"
        + (f" · linked repos: {', '.join(f'`{r}`' for r in data['linked_repos'])}" if data["linked_repos"] else ""),
        f"- **Graph:** {c['code_files']} code files · {c['code_symbols']} symbols · {c['code_edges']} resolved code edges · "
        f"{c['routes']} HTTP routes · {c['scars']} scars",
        "",
        "### Architecture (modules by size)",
        "",
    ]
    deps: dict[str, list[str]] = {}
    for e in data["module_edges"]:
        if e["kind"] != "code":
            continue
        deps.setdefault(f"{e['from']['repo']}:{e['from']['module']}", []).append(e["to"]["module"])
    for m in data["modules"][:12]:
        key = f"{m['repo']}:{m['module']}"
        uses = list(dict.fromkeys(deps.get(key, [])))[:5]
        out.append(f"- `{m['module']}/` ({m['repo']}) — {m['files']} files, {m['symbols']} symbols, "
                   f"{', '.join(m['languages']) or 'n/a'}" + (f"; uses {', '.join(f'`{u}`' for u in uses)}" if uses else ""))
    if data["routes"]:
        out += ["", f"### API routes ({len(data['routes'])})", ""]
        for r in data["routes"][:25]:
            consumers = f" ← {len(r['consumers'])} consumer(s)" if r["consumers"] else ""
            out.append(f"- `{r['method']} {r['path']}` → `{r['handler']}` ({r['file']}:{r['line']}){consumers}")
        if len(data["routes"]) > 25:
            out.append(f"- … {len(data['routes']) - 25} more (`aether docs` lists all)")
    if data["decisions"]:
        out += ["", "### Architecture decisions", ""]
        for d in data["decisions"][:10]:
            body = " ".join(str(d["body"]).split())
            out.append(f"- **{d['title']}** — {body[:220]}{'…' if len(body) > 220 else ''}")
    if data["scars"]:
        out += ["", "### Critical scars (read before editing these files)", ""]
        for s in data["scars"][:12]:
            fix = f" Fix: {s['fix_applied'][:140]}" if s["fix_applied"] else ""
            out.append(f"- [{s['severity']}] `{s['file_path']}` — {s['error_summary'][:160]}.{fix}")
    if data["hotspots"]:
        out += ["", "### Hotspots (highest technical-debt risk)", ""]
        for h in data["hotspots"][:5]:
            why = f" — {'; '.join(h['reasons'])}" if h["reasons"] else ""
            out.append(f"- `{h['file']}` risk {h['risk_score']:.0f}/100 ({h['level']}){why}")
    out += [
        "",
        "### Agent workflow (Aether MCP tools)",
        "",
        "1. `query_smart_context` before opening large files; `check_scars` + `impact_analysis` before editing.",
        "2. `create_snapshot` before risky multi-file edits; `semantic_diff` to review what changed.",
        "3. On failing tests: `prepare_heal_context`; after the fix: `record_scar`.",
        "4. Before ending a session: `save_session_checkpoint` (resume later with `resume_session`).",
    ]
    return "\n".join(out)


def write_rules(root: Path, body: str, targets: list[str], can_write: Any) -> list[dict[str, Any]]:
    """Upsert ``body`` into each target file under ``root``. ``can_write(rel) -> bool`` enforces policy."""
    results: list[dict[str, Any]] = []
    for rel in targets:
        rel_norm = rel.replace("\\", "/").lstrip("/")
        target = (root / rel_norm).resolve()
        if root.resolve() not in target.parents:
            results.append({"path": rel_norm, "action": "refused", "reason": "outside the project root"})
            continue
        if not can_write(rel_norm):
            results.append({"path": rel_norm, "action": "refused", "reason": "read-only or denied by .aether/policy.json"})
            continue
        existing = ""
        if target.is_file():
            with target.open("r", encoding="utf-8", newline="") as fh:
                existing = fh.read()
        updated = upsert_block(existing, body)
        if updated == existing:
            results.append({"path": rel_norm, "action": "unchanged"})
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        tmp = target.with_name(target.name + ".aether-tmp")
        with tmp.open("w", encoding="utf-8", newline="") as fh:
            fh.write(updated)
        os.replace(tmp, target)
        results.append({"path": rel_norm, "action": "created" if not existing else "updated"})
    return results
